<template>
	<view class="container">
		<u-loading-page
		:loading="true" 
		v-if="load"
		fontSize="28rpx" />
		<block v-else>
		<view class="top" :style="{'backgroundImage':`url(${baseUrl}/uni/jf-shop-bg.png)`}">
			<view class="top-info">
				<view class="tit">我的余额(元)</view>
				<view class="money">{{balance}}</view>
				<view class="mingxi" @click="toNext('/pages/my/recharge-list')">充值记录</view>
			</view>
		</view>
		<view class="info">
			<view class="info-type">
				<view class="title">支付方式</view>
				<view class="type-items" v-if="pay_list.length>0">
					<view class="type-item" :class="{'act':form.pay_code==item.pay_code}" @click="changePay(item)" v-for="(item,index) in pay_list" :key="index">
						<image :src="form.pay_code==item.pay_code?item.pay_sel_img:item.pay_img" mode="widthFix" class="tx-img" />
						<text>{{item.pay_name}}</text>
					</view>
				</view>
			</view>
			<view class="info-type">
				<view class="title">充值金额</view>
				<view class="input-container">
					<text>¥</text>
					<u-input
					    placeholder="请输入充值金额"
						border="none"
						type="number"
						placeholderClass="placeholder28"
						v-model="form.money"
						fontSize="50rpx"
					    clearable />
				</view>
			</view>
			<view class="submit">
				<button type="default" class="submit-btn" @click="submit"
					:disabled="submitDisabled || pay_config.pay_open==0">{{pay_config.pay_open==0?'充值暂未开放':'立即充值'}}</button>
			</view>
		</view>
		</block>
	</view>
</template>

<script>
	var validate = require("@/components/validate/validate.js");
	var _this;
	export default {
		data() {
			return {
				form:{
					step:1,
					money:'',
					pay_code:'',
				},
				balance:'',
				mobile:'',
				pay_config:{},
				pay_list:[],
				submitDisabled:false,
			}
		},
		onLoad(e) {
			_this = this;
			_this.tijiao()
		},
		methods: {
			changePay(item){
				if (item.pay_code==this.form.pay_code) {
					return
				}
				this.form.pay_code = item.pay_code
			},
			submit(){
				_this.form.step = 2
				_this.tijiao()
			},
			//提交
			async tijiao(){
				// #ifdef MP-WEIXIN
				let openid = uni.getStorageSync('unionid')?uni.getStorageSync('unionid'):uni.getStorageSync('openid')
				this.form.is_xcx = 1
				this.form.openid = openid
				// #endif
				if (_this.form.step == 2) {
					var rule = [
						{
							name: 'money',
							rules: ['require', 'number'],
							errorMsg: {
								require: '请输入充值金额',
								number: '充值金额只能为数字'
							}
						}
						];
					// 是否全部通过，返回Boolean
					let checked = validate.check(this.form, rule);
					if (!checked) {
						// 获取错误信息
						let err = validate.getError();
						uni.$u.toast(err[0])
						return;
					}
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/chongzhi',_this.form)
				if (data.code==200) {
					uni.$u.toast(data.msg,()=>{
						_this.toNext(`/pages/my/recharge-list`,true)
					})
				}else if(data.code == -1){
					_this.mobile = data.result.mobile
					_this.balance = data.result.balance
					_this.pay_config = data.result.pay_config
					_this.pay_list = data.result.pay_list
					if (_this.pay_list.length>0) {
						_this.form.pay_code = _this.pay_list[0]['pay_code']
					}
					if (_this.load) {
						_this.load = false
					}
				}else if(data.code==50){
					if(_this.form.pay_code == 'alipayMobile'){
						// location.href = data.result.url
						location.replace(data.result.url)
						// _this.finish()
					}else if (_this.form.pay_code == 'weixinH5') {
						location.href = data.result.url
						uni.showModal({
							title:'提示',
							content:'请确认是否已完成支付',
							confirmText:'已完成支付',
							cancelText:'未完成支付',
							success(res) {
								_this.queryOrder(data.result.order_sn)
							}
						})
					}else{
						let wx_result = data.result.wx_result
						function onBridgeReady(){
						   WeixinJSBridge.invoke(
						      'getBrandWCPayRequest', wx_result,
						      function(res){
								  if(res.err_msg == "get_brand_wcpay_request:ok" ){
										// 使用以上方式判断前端返回,微信团队郑重提示：
										//res.err_msg将在用户支付成功后返回ok，但并不保证它绝对可靠。
										uni.$u.toast('支付成功',()=>{
											_this.toNext(`/pages/my/recharge-list`,true)
										})
								  }else if (res.err_msg=="get_brand_wcpay_request:cancel") {
										uni.$u.toast('支付过程中用户取消',()=>{
											_this.toNext(`/pages/my/recharge-list`,true)
										})
								  }else{
									  uni.$u.toast('支付失败',()=>{
											_this.toNext(`/pages/my/recharge-list`,true)
										})
								  }
						   }); 
						}
						if (typeof WeixinJSBridge == "undefined"){
						   if( document.addEventListener ){
						       document.addEventListener('WeixinJSBridgeReady', onBridgeReady, false);
						   }else if (document.attachEvent){
						       document.attachEvent('WeixinJSBridgeReady', onBridgeReady); 
						       document.attachEvent('onWeixinJSBridgeReady', onBridgeReady);
						   }
						}else{
						   onBridgeReady();
						}
					}
				}else if(data.code==-50){
					console.log(data);
					uni.requestPayment({
						provider: 'wxpay',
						timeStamp: data.result.timeStamp+'',
						nonceStr: data.result.nonceStr,
						package: data.result.package,
						signType: data.result.signType,
						paySign: data.result.sign,
						success(res) {
							console.log('success:' + JSON.stringify(res));
							_this.$u.toast('支付成功',()=>{
								_this.toNext('/pages/my/recharge-list',true)
							})
						},
						fail(err) {
							_this.$u.toast('支付失败',()=>{
								_this.toNext('/pages/my/recharge-list',true)
							})
							console.log('fail:' + JSON.stringify(err));
						}
					});
				}else{
					uni.$u.toast(data.msg)
				}
			},
			//查询订单支付状态
			async queryOrder(order_sn){
				let params = {
					order_sn
				}
				const data = await _this.$post('port/chaxun_order', params)
				if (data.code==200) {
					_this.toNext(`/pages/my/recharge-list`,true)
				} else if(data.code==100){
					_this.toNext(`/pages/my/recharge-list`,true)
				}else{
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}
			}
		}
	}
</script>

